import{_ as e,c as l,o as t,ah as i}from"./chunks/framework.l36K22_3.js";const b=JSON.parse('{"title":"React 基础","description":"","frontmatter":{},"headers":[],"relativePath":"knowledge/react/basics.md","filePath":"knowledge/react/basics.md","lastUpdated":1697186195000}'),r={name:"knowledge/react/basics.md"};function c(o,a,h,n,s,d){return t(),l("div",null,a[0]||(a[0]=[i('<h1 id="react-基础" tabindex="-1">React 基础 <a class="header-anchor" href="#react-基础" aria-label="Permalink to &quot;React 基础&quot;">​</a></h1><h2 id="react-是什么" tabindex="-1">React 是什么 <a class="header-anchor" href="#react-是什么" aria-label="Permalink to &quot;React 是什么&quot;">​</a></h2><h3 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h3><ul><li>用于构建 Web 和原生交互界面的库</li><li>React 用组件创建用户界面</li><li>通俗来讲：==是一个将数据渲染为 HTML 视图的开源 JS 库==</li></ul><h3 id="其他信息" tabindex="-1">其他信息 <a class="header-anchor" href="#其他信息" aria-label="Permalink to &quot;其他信息&quot;">​</a></h3><ul><li>Facebook 开发，并且开源</li></ul><h2 id="为什么使用-react" tabindex="-1">为什么使用 React? <a class="header-anchor" href="#为什么使用-react" aria-label="Permalink to &quot;为什么使用 React?&quot;">​</a></h2><ul><li>原生 JS 使用 DOM-API 修改 UI 代码很繁琐，效率低下，React 可以解决这种问题</li><li>原生 JS 直接操作 DOM，浏览器会大量重绘重排，React 可以解决这种问题</li><li>原生 JS 没有组件化方案好用，代码复用率很低，</li><li>React 采用组件化模式，React 让你可以通过组件来构建用户界面</li><li>React 使用声明式编码</li><li>React 使用虚拟 DOM，将数据映射成虚拟 DOM,再生成真实 DOM,当数据变化的时候，会对原有的虚拟 DOM 和新的虚拟 DOM 进行比较,再生成真实 DOM。</li><li>React 使用 DOM diffing 算法，最小化页面重绘</li></ul><h3 id="特点" tabindex="-1">特点 <a class="header-anchor" href="#特点" aria-label="Permalink to &quot;特点&quot;">​</a></h3><p>声明式设计 − 为你应用的每一个状态设计简洁的视图，当数据改变时 React 能有效地更新并正确地渲染组件。</p><ul><li>高效 −React 采用 Virtual DOM(虚拟 DOM), 极大的提升了 UI 渲染(更新)效率。</li><li>灵活 −React 允许你结合其他框架或库一起使用。</li><li>JSX − JSX 是 JavaScript 语法的扩展。JSX 可以很好地描述 UI 应该呈现出它应有交互的本质形式。</li><li>组件 − 通过 React 构建组件，使得代码更加容易得到复用，能够很好的应用在大项目的开发中。</li><li>单向响应的数据流 − React 采用了单向响应的数据流，使组件状态更容易维护, 组件模块化更易于快速开发。</li></ul><h2 id="怎么用-react" tabindex="-1">怎么用 React? <a class="header-anchor" href="#怎么用-react" aria-label="Permalink to &quot;怎么用 React?&quot;">​</a></h2><h3 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h3><ul><li>ES6</li><li>Class</li><li>js 基础</li></ul><h3 id="文档" tabindex="-1">文档 <a class="header-anchor" href="#文档" aria-label="Permalink to &quot;文档&quot;">​</a></h3><ul><li>中文文档: <a href="https://zh-hans.react.dev/learn" target="_blank" rel="noreferrer">zh-hans.react.dev/learn</a></li></ul>',16)]))}const R=e(r,[["render",c]]);export{b as __pageData,R as default};
